import os, json, re, json

def load_all_grids():
    """Load all grids from session history"""
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        return {}

    # Find the JSONL file for this instance
    sessions_path = os.path.join(session_dir, '..', 'sessions')
    jsonl_file = None

    # Try different path structures
    for parent in [session_dir]:
        candidate = os.path.join(parent, '../../sessions', os.path.basename(parent), '.jsonl')
        if os.path.exists(candidate):
            jsonl_file = candidate
            break

        candidate2 = os.path.join(sessions_path, os.path.basename(parent) + '.jsonl')
        if os.path.exists(candidate2):
            jsonl_file = candidate2
            break

    if not jsonl_file:
        # Try glob approach
        for root, dirs, files in os.walk(session_dir):
            for f in files:
                if f.endswith('.jsonl'):
                    jsonl_file = os.path.join(root, f)
                    break
            if jsonl_file:
                break

    if not jsonl_file or not os.path.exists(jsonl_file):
        print(f"Could not find JSONL file at {jsonl_file}")
        return {}

    G = {}
    try:
        with open(jsonl_file, 'r') as f:
            content = f.read()

        # Find all demo/test grid blocks
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+?)(?=\n\n|$)'
        matches = list(re.finditer(pattern, content, re.DOTALL))

        # Build grids from raw text
        pos = 0
        for i, m in enumerate(matches):
            label = m.group(1)
            h, w = int(m.group(2)), int(m.group(3))
            rows = []

            # Extract row data (space-separated digits)
            remaining = content[m.end():m.end()+h*w]

            # Parse line by line until we have enough
            chars = list(remaining.split('\n'))
            for line in chars:
                parts = line.strip().split()
                rows.append([int(x) for x in parts])
                if len(rows) >= h:
                    break

            key = label[:label.rfind('(')]  # Remove dimension part
            if key not in G:
                G[key] = rows[:h][:w]  # Take exactly h rows

            print(f"{key}: {len(G[key])}x{len(G[key][0]) if G[key] else 0}")

    except Exception as e:
        print(f"Error parsing grids: {e}")
        import traceback
        traceback.print_exc()

    return G

