# Also double-check by running flood_fill_interior fresh
def flood_fill_interior(grid):
    """Fill interior 0-regions (not connected to grid edge) with color 4."""
    rows = len(grid)
    cols = len(grid[0])

    # Mark all edge-connected 0s
    visited = [[False] * cols for _ in range(rows)]
    queue = []

    # Add all edge 0s to queue
    for i in range(rows):
        if grid[i][0] == 0:
            queue.append((i, 0))
            visited[i][0] = True
        if grid[i][cols-1] == 0:
            queue.append((i, cols-1))
            visited[i][cols-1] = True
    for j in range(cols):
        if grid[0][j] == 0:
            queue.append((0, j))
            visited[0][j] = True
        if grid[rows-1][j] == 0:
            queue.append((rows-1, j))
            visited[rows-1][j] = True

    # BFS to mark all exterior 0s
    import collections
    q = collections.deque(queue)
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and not visited[nr][nc]:
                    visited[nr][nc] = True
                    q.append((nr, nc))

    # Fill remaining 0s with 4
    new_grid = [row[:] for row in grid]
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0 and not visited[i][j]:
                new_grid[i][j] = 4

    return new_grid

